const PROGRAMME_ID = 'prog-customer-service-onboarding';

const module = (id, orderIndex, title, summary, estimatedMinutes, source, prerequisiteModuleIds) => ({
  id,
  programmeId: PROGRAMME_ID,
  orderIndex,
  title,
  summary,
  estimatedMinutes,
  prerequisiteModuleIds: prerequisiteModuleIds || [],
  // Customer Service Team requires NO learner sign-off and NO reviewer
  // sign-off anywhere in this programme (user-confirmed requirement).
  requiresSignoff: false,
  status: 'FINAL_TRUTH',
  source,          // === sourceReference in the data model
});

const lesson = (id, moduleId, orderIndex, title, content, estimatedMinutes, source) => ({
  id,
  moduleId,
  orderIndex,
  title,
  content,
  estimatedMinutes,
  required: true,
  status: 'FINAL_TRUTH',
  source,
});

